const payload = $json.body || $json;
const data = payload.data || payload;
const key = data.key || payload.key || {};
const message = data.message || payload.message || {};
const text = String(
  message.conversation ||
  message.extendedTextMessage?.text ||
  message.imageMessage?.caption ||
  message.videoMessage?.caption ||
  data.text ||
  payload.text ||
  payload.messageText ||
  ''
).trim();
const remoteJid = String(
  key.remoteJid ||
  data.key?.remoteJid ||
  data.remoteJid ||
  payload.remoteJid ||
  payload.from ||
  payload.sender ||
  ''
);
const fromMe = Boolean(key.fromMe || data.fromMe || payload.fromMe);
const event = payload.event || payload.eventName || data.event || '';
const instanceName = payload.instance || payload.instanceName || data.instanceName || '';

if (!text || fromMe || remoteJid.includes('@g.us')) {
  return [];
}

return [{
  json: {
    event,
    instanceName,
    remoteJid,
    text,
    pushName: data.pushName || payload.pushName || '',
    receivedAt: new Date().toISOString()
  }
}];

const inbound = $('Preparar Mensaje WhatsApp').first().json;
const config = $json || {};
const bot = config.bot || {
  name: 'Chatbot WhatsApp',
  businessName: 'Empresa',
  tone: 'profesional',
  knowledge: 'Responde de forma breve y pide datos si el cliente quiere comprar.'
};
const knowledge = String(bot.knowledge || '');
const text = String(inbound.text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

function linesFor(patterns) {
  return knowledge
    .split(/\n+/)
    .filter((line) => patterns.some((pattern) => pattern.test(line.toLowerCase())))
    .join('\n');
}

function fallbackReply() {
  if (/precio|valor|cuanto|cuesta|vale|catalogo/.test(text)) {
    const prices = linesFor([/precio/, /cop/, /\$|[0-9][0-9.,]+/]);
    return prices
      ? `Claro. Estos son los precios de ${bot.businessName || bot.name}:\n${prices}\n\nSi deseas comprar, dime talla, color, cantidad y ciudad.`
      : `Claro. Puedo ayudarte con precios de ${bot.businessName || bot.name}. Dime que producto te interesa.`;
  }
  if (/envio|domicilio|entrega|pais|ciudad/.test(text)) {
    const shipping = linesFor([/envio/, /entrega/, /domicilio/, /transportadora/]);
    return shipping || 'Hacemos envios segun ciudad. Dime tu ciudad y te confirmo costo y tiempo de entrega.';
  }
  if (/pago|contra|nequi|daviplata|transferencia/.test(text)) {
    const payments = linesFor([/pago/, /nequi/, /daviplata/, /transferencia/, /contra/]);
    return payments || 'Puedes consultar metodos de pago y pago contra entrega. Dime tu ciudad para confirmar disponibilidad.';
  }
  if (/calidad|tela|material|garantia|marca/.test(text)) {
    const quality = linesFor([/calidad/, /tela/, /algodon/, /garantia/, /costura/]);
    return quality || 'Te puedo contar la calidad, material y garantia del producto. Que referencia te interesa?';
  }
  return `Hola, soy el asistente de ${bot.businessName || bot.name}. Te puedo ayudar con precios, calidad, envios, pagos y pedidos. Que deseas saber?`;
}

return [{
  json: {
    inbound,
    instanceName: inbound.instanceName || config.instanceName,
    remoteJid: inbound.remoteJid,
    message: inbound.text,
    bot,
    aiRequest: {
      message: inbound.text,
      bot,
      conversation: [{ role: 'user', text: inbound.text, channel: 'whatsapp', from: inbound.remoteJid }],
      fallbackReply: fallbackReply()
    }
  }
}];

const prepared = $('Preparar Consulta IA').first().json;
const ai = $json || {};
const reply = ai.reply || prepared.aiRequest.fallbackReply;

return [{
  json: {
    instanceName: prepared.instanceName,
    remoteJid: prepared.remoteJid,
    text: reply,
    source: ai.ok ? 'openai+n8n-whatsapp' : 'fallback+n8n-whatsapp',
    intent: ai.intent || 'general',
    lead_status: ai.lead_status || 'nuevo'
  }
}];
